1	/**
2	 * Private row → domain mappers for the repository layer.
3	 *
4	 * SQLite stores branded ids as plain text and collections as JSON strings, so
5	 * exactly one place is allowed to re-apply the brands and parse the JSON: here.
6	 * Services never see a `*Row` type.
7	 */
8	import type {
9	  ActivityEventRow,
10	  AttachmentRow,
11	  CommentRow,
12	  InvitationRow,
13	  InvoiceRow,
14	  IssueRow,
15	  LabelRow,
16	  MemberRow,
17	  NotificationPreferenceRow,
18	  NotificationRow,
19	  OrganizationRow,
20	  OrganizationUsageRow,
21	  ProjectRow,
22	  SubscriptionRow,
23	  UserRow,
24	} from "@/server/db";
25	import type {
26	  ActivityAction,
27	  ActivityEvent,
28	} from "@/types/activity";
29	import type { Invoice, Subscription } from "@/types/billing";
30	import type { Comment } from "@/types/comment";
31	import type {
32	  ActivityId,
33	  AttachmentId,
34	  CommentId,
35	  InvitationId,
36	  IsoTimestamp,
37	  IssueId,
38	  LabelId,
39	  MemberId,
40	  NotificationId,
41	  OrgId,
42	  ProjectId,
43	  SubscriptionId,
44	  UserId,
45	} from "@/types/common";
46	import type { Issue, IssueAttachment, IssueLabel } from "@/types/issue";
47	import type { Invitation, Member, User } from "@/types/member";
48	import type {
49	  Notification,
50	  NotificationChannel,
51	  NotificationPreference,
52	} from "@/types/notification";
53	import type {
54	  Organization,
55	  OrganizationUsage,
56	} from "@/types/organization";
57	import type { Project } from "@/types/project";
58	
59	/** Every id column is text in SQLite; the brand is re-applied on the way out. */
60	export function brandId<T extends string>(value: string): T {
61	  return value as T;
62	}
63	
64	export function brandStamp(value: string): IsoTimestamp {
65	  return value as IsoTimestamp;
66	}
67	
68	export function brandStampOrNull(value: string | null): IsoTimestamp | null {
69	  return value === null ? null : brandStamp(value);
70	}
71	
72	/** Tolerant JSON array read: a corrupt column degrades to an empty list. */
73	export function parseJsonArray<T>(raw: string): readonly T[] {
74	  try {
75	    const parsed: unknown = JSON.parse(raw);
76	    return Array.isArray(parsed) ? (parsed as T[]) : [];
77	  } catch {
78	    return [];
79	  }
80	}
81	
82	export function parseJsonObject(
83	  raw: string,
84	): Readonly<Record<string, string | number | boolean | null>> {
85	  try {
86	    const parsed: unknown = JSON.parse(raw);
87	    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
88	      return parsed as Record<string, string | number | boolean | null>;
89	    }
90	    return {};
91	  } catch {
92	    return {};
93	  }
94	}
95	
96	export function toUser(row: UserRow): User {
97	  return {
98	    id: brandId<UserId>(row.id),
99	    email: row.email,
100	    name: row.name,
101	    avatarUrl: row.avatarUrl,
102	    timezone: row.timezone,
103	    emailVerifiedAt: brandStampOrNull(row.emailVerifiedAt),
104	    createdAt: brandStamp(row.createdAt),
105	    updatedAt: brandStamp(row.updatedAt),
106	  };
107	}
108	
109	export function toOrganization(row: OrganizationRow): Organization {
110	  return {
111	    id: brandId<OrgId>(row.id),
112	    name: row.name,
113	    slug: row.slug,
114	    ownerId: brandId<UserId>(row.ownerId),
115	    plan: row.plan,
116	    logoUrl: row.logoUrl,
117	    trialEndsAt: brandStampOrNull(row.trialEndsAt),
118	    settings: {
119	      defaultIssueStatus: row.defaultIssueStatus,
120	      allowPublicProjects: row.allowPublicProjects,
121	      requireTwoFactor: row.requireTwoFactor,
122	      digestHourUtc: row.digestHourUtc,
123	      enabledFlagOverrides: parseJsonArray<string>(row.enabledFlagOverrides),
124	    },
125	    createdAt: brandStamp(row.createdAt),
126	    updatedAt: brandStamp(row.updatedAt),
127	    archivedAt: brandStampOrNull(row.archivedAt),
128	  };
129	}
130	
131	export function toUsage(row: OrganizationUsageRow): OrganizationUsage {
132	  return {
133	    orgId: brandId<OrgId>(row.orgId),
134	    seatsUsed: row.seatsUsed,
135	    projectsUsed: row.projectsUsed,
136	    issuesUsed: row.issuesUsed,
137	    storageMbUsed: row.storageMbUsed,
138	    measuredAt: brandStamp(row.measuredAt),
139	  };
140	}
141	
142	export function toMember(row: MemberRow): Member {
143	  return {
144	    id: brandId<MemberId>(row.id),
145	    orgId: brandId<OrgId>(row.orgId),
146	    userId: brandId<UserId>(row.userId),
147	    role: row.role,
148	    status: row.status,
149	    invitedBy: row.invitedBy === null ? null : brandId<UserId>(row.invitedBy),
150	    joinedAt: brandStampOrNull(row.joinedAt),
151	    lastSeenAt: brandStampOrNull(row.lastSeenAt),
152	    createdAt: brandStamp(row.createdAt),
153	    updatedAt: brandStamp(row.updatedAt),
154	    archivedAt: brandStampOrNull(row.archivedAt),
155	  };
156	}
157	
158	export function toInvitation(row: InvitationRow): Invitation {
159	  return {
160	    id: brandId<InvitationId>(row.id),
161	    orgId: brandId<OrgId>(row.orgId),
162	    email: row.email,
163	    role: row.role,
164	    invitedBy: brandId<UserId>(row.invitedBy),
165	    token: row.tokenHash,
166	    expiresAt: brandStamp(row.expiresAt),
167	    acceptedAt: brandStampOrNull(row.acceptedAt),
168	    revokedAt: brandStampOrNull(row.revokedAt),
169	    createdAt: brandStamp(row.createdAt),
170	    updatedAt: brandStamp(row.updatedAt),
171	  };
172	}
173	
174	export function toProject(row: ProjectRow): Project {
175	  return {
176	    id: brandId<ProjectId>(row.id),
177	    orgId: brandId<OrgId>(row.orgId),
178	    name: row.name,
179	    slug: row.slug,
180	    key: row.key,
181	    description: row.description,
